    adj = {i: [] for i in range(n)}
    in_degree = {i: 0 for i in range(n)}

    for u, v in preserve_pairs:
        adj[u].append(v)
        in_degree[v] += 1

    # Kahn's algorithm
    queue = [i for i in range(n) if in_degree[i] == 0]
    queue.sort()  # Optional: deterministic order for ties
    result_indices = []

    while queue:
        u = queue.pop(0)
        result_indices.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # If not all indices processed, there's a cycle (shouldn't happen here)
    if len(result_indices) != n:
        raise ValueError("Cycle detected in constraints")

    # Construct output list based on topological order of original indices
    output = [0] * n
    for pos, orig_idx in enumerate(result_indices):
        output[pos] = val_at[orig_idx]

